            landing_about_p1: 'SeeYou는 간단한 아이디어에서 시작되었습니다: 친구들과 중요한 순간을 공유하는 것은 쉽고, 친밀하고, 안전해야 한다는 것입니다.',
            landing_about_p2: '우리는 소셜 네트워크가 추억을 간직하고 중요한 사람들과 가까이 지내는 데 도움이 되어야 한다고 믿습니다. 그래서 각 Tic은 사진, 그 이야기, 장소, 그 순간의 음악을 하나로 모읍니다.',
            landing_about_p3: '우리는 당신의 개인정보를 존중하고 데이터에 대한 통제권을 제공하면서, 웹과 안드로이드에서 세심한 경험을 제공하기 위해 노력하고 있습니다.',
            landing_about_p4: '질문이나 제안이 있으신가요? 아래로 연락 주세요:',
            landing_footer_tagline: '당신 인생의 추억을 친구들과 공유하는 소셜 네트워크.',
            landing_footer_product: '제품',
