            landing_footer_rights: '모든 권리 보유.',
            landing_cookie_text: 'SeeYou가 작동하도록, 그리고 당신의 허락하에 경험을 개선하기 위해 쿠키를 사용합니다.',
            landing_cookie_configure: '설정',
